def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into a list of individual characters
    characters = test.split(" ")

    # Find the maximum frequency of any character in the list
    max_frequency = 0
    for char in characters:
        if char != '' and characters.count(char) > max_frequency:
            max_frequency = characters.count(char)

    # Build the result dictionary with characters that have the maximum frequency
    result = {}
    if max_frequency > 0:
        for char in characters:
            if characters.count(char) == max_frequency:
                result[char] = max_frequency

    return result
