def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # If the text contains spaces, split it into words using whitespace as the delimiter
    if " " in txt:
        return txt.split()

    # If the text contains commas but no spaces, replace commas with spaces and then split
    elif "," in txt:
        return txt.replace(',', ' ').split()

    # If neither spaces nor commas are present, count the lower-case letters
    # whose position in the alphabet (0-indexed) is even (i.e., 'a'=0, 'c'=2, 'e'=4, etc.)
    else:
        return len([char for char in txt if char.islower() and ord(char) % 2 == 0])
